import{_ as l,a0 as a,w as p,s as n,ao as S,I as s,x as o,a1 as r,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"FreeDOS 如何启动 | LCTT x X-CMD","titleTemplate":false,"description":"FreeDOS 如何启动 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"FreeDOS 如何启动 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"FreeDOS 如何启动 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210608 How FreeDOS boots","title":"FreeDOS 如何启动","tag":"202106","desc":""},"relativePath":"202106/20210608 How FreeDOS boots.md","filePath":"[post].md"}'),i={name:"202106/20210608 How FreeDOS boots.md"};function O(c,e,u,m,D,F){const t=a("Link");return p(),n("div",null,[e[15]||(e[15]=S('<h1 id="freedos-如何启动" tabindex="-1">FreeDOS 如何启动 <a class="header-anchor" href="#freedos-如何启动" aria-label="Permalink to “FreeDOS 如何启动”">​</a></h1><blockquote><p>概述你的计算机如何引导和启动一个像 FreeDOS 这样的简单操作系统。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/20/140809fpkrcnow8npnow8p.jpg" alt=""></p><p>在使用 DOS 计算机的过程中，我很欣赏的一点是，引导过程相对容易理解。在 DOS 中没有太多的变动组件。而今天，我想和大家分享一下电脑是如何引导和启动像 FreeDOS 这样的简单操作系统的概况。</p><h3 id="初始引导" tabindex="-1">初始引导 <a class="header-anchor" href="#初始引导" aria-label="Permalink to “初始引导”">​</a></h3><p>当你打开计算机的电源时，系统会进行一些自我检查，如验证内存和其他组件。这被称为<ruby>开机自检<rt>Power On Self Test</rt></ruby>（POST）。POST 之后，计算机使用一个硬编码指令，告诉它在哪里找到加载操作系统的指令。这就是“<ruby>引导加载程序<rt>boot loader</rt></ruby>”，通常它将试图找到硬盘上的<ruby>主引导记录<rt>Master Boot Record</rt></ruby>（MBR）。然后，MBR 加载主操作系统，在这里就是 FreeDOS。</p><p>这个定位一个信息以便计算机能够加载操作系统的下一个部分的过程被称为“<ruby>引导<rt>bootstrapping</rt></ruby>”，来自于“<ruby>通过你自己的努力振作起来<rt>picking yourself up by your bootstraps</rt></ruby>”的古老说法。正是从这个用法中，我们采用了“<ruby>引导<rt>boot</rt></ruby>”一词来表示启动你的计算机。</p><h3 id="内核" tabindex="-1">内核 <a class="header-anchor" href="#内核" aria-label="Permalink to “内核”">​</a></h3><p>当计算机加载 FreeDOS 内核时，内核所做的第一件事就是识别用户所表示要使用的任何参数。它被保存在一个叫做 <code>FDCONFIG.SYS</code> 的文件中，与内核保存在同一个根目录下。如果 <code>FDCONFIG.SYS</code> 不存在，那么 FreeDOS 的内核就会寻找一个叫做 <code>CONFIG.SYS</code> 的替代文件。</p><p>如果你在 20 世纪 80 年代或 90 年代使用过 DOS，你可能对 <code>CONFIG.SYS</code> 文件很熟悉。从 1999 年起，FreeDOS 首先寻找 <code>FDCONFIG.SYS</code>，以防你的 DOS 系统与其他 DOS（如 MS-DOS）做了 <em>双启动</em>。请注意，MS-DOS 只使用 <code>CONFIG.SYS</code> 文件。因此，如果你用同一个硬盘同时启动 FreeDOS 和 MS-DOS，MS-DOS 使用 <code>CONFIG.SYS</code> 来配置自己，而 FreeDOS 则使用 <code>FDCONFIG.SYS</code>。这样一来，双方都可以使用自己的配置。</p><p><code>FDCONFIG.SYS</code> 可以包含一些配置设置，其中之一是 <code>SHELL=</code> 或 <code>SHELLHIGH=</code>。任何一个都会指示内核加载这个程序作为用户的交互式 shell。</p><p>如果 <code>FDCONFIG.SYS</code> 和 <code>CONFIG.SYS</code> 都不存在，那么内核就会假定几个默认值，包括在哪里找到 shell。如果你在启动 FreeDOS 系统时看到 “Bad or missing Command Interpreter” 的信息，这意味着 <code>SHELL=</code> 或 <code>SHELLHIGH=</code> 指向了一个在你系统中不存在的 shell 程序。</p><p><img src="https://opensource.com/sites/default/files/uploads/bad-missing-command.png" alt="Bad or missing Command Interpreter" title="Bad or missing Command Interpreter"></p><p>你可以通过查看 <code>SHELL=</code> 或 <code>SHELLHIGH=</code> 行来调试这个问题。如果做不到这一点，请确保你在 FreeDOS 系统的根目录下有一个名为 <code>COMMAND.COM</code> 的程序。它就是 <em>shell</em>，我接下来会讲到它。</p><h3 id="shell" tabindex="-1">shell <a class="header-anchor" href="#shell" aria-label="Permalink to “shell”">​</a></h3><p>在 DOS 系统中，“shell” 一词通常是指一个命令行解释器：一个交互式程序，它从用户那里读取指令，然后执行它们。在这里，FreeDOS 的 shell 与 Linux 的 Bash shell 相似。</p><p>除非你用 <code>SHELL=</code> 或 <code>SHELLHIGH=</code> 要求内核加载一个不同的 shell，否则 DOS 上的标准命令行 shell 被称为 <code>COMMAND.COM</code>。当 <code>COMMAND.COM</code> 启动时，它也寻找一个文件来配置自己。默认情况下，<code>COMMAND.COM</code> 会在根目录下寻找一个名为 <code>AUTOEXEC.BAT</code> 的文件。<code>AUTOEXEC.BAT</code> 是一个“批处理文件”，它包含一组启动时运行的指令，大致类似于 Linux 上 Bash 启动时读取的 <code>~/.bashrc</code> “资源文件”。</p><p>你可以在 <code>FDCONFIG.SYS</code> 文件中用 <code>SHELL=</code> 或 <code>SHELLHIGH=</code> 改变 shell 以及 shell 的启动文件。FreeDOS 1.3 RC4 安装程序将系统设置为读取 <code>FDAUTO.BAT</code> 而不是 <code>AUTOEXEC.BAT</code>。这与内核读取另一个配置文件的原因相同；你可以在硬盘上用另一个 DOS 双启动 FreeDOS。FreeDOS 将使用 <code>FDAUTO.BAT</code> 而 MS-DOS 将使用 <code>AUTOEXEC.BAT</code>。</p><p>如果没有像 <code>AUTOEXEC.BAT</code> 这样的启动文件，shell 将简单地提示用户输入日期和时间。</p><p><img src="https://opensource.com/sites/default/files/uploads/no-autoexec.png" alt="Without AUTOEXEC.BAT, the shell will prompt for date and time" title="Without AUTOEXEC.BAT, the shell will prompt for date and time"></p><p>就是这些了。当 FreeDOS 加载了内核，而内核也加载了 shell，FreeDOS 就准备好让用户输入命令了。</p><p><img src="https://opensource.com/sites/default/files/uploads/freedos-boot.png" alt="FreeDOS is ready for you to enter your first command" title="FreeDOS is ready for you to enter your first command"></p><hr>',23)),s("p",null,[e[1]||(e[1]=o("via: ",-1)),r(t,{href:"https://opensource.com/article/21/6/freedos-boots"},{default:d(()=>[...e[0]||(e[0]=[o("https://opensource.com/article/21/6/freedos-boots",-1)])]),_:1})]),s("p",null,[e[6]||(e[6]=o("作者：",-1)),r(t,{href:"https://opensource.com/users/jim-hall"},{default:d(()=>[...e[2]||(e[2]=[o("Jim Hall",-1)])]),_:1}),e[7]||(e[7]=o(" 选题：",-1)),r(t,{href:"https://github.com/lujun9972"},{default:d(()=>[...e[3]||(e[3]=[o("lujun9972",-1)])]),_:1}),e[8]||(e[8]=o(" 译者：",-1)),r(t,{href:"https://github.com/geekpi"},{default:d(()=>[...e[4]||(e[4]=[o("geekpi",-1)])]),_:1}),e[9]||(e[9]=o(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[5]||(e[5]=[o("wxy",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=o("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原创编译，",-1)),r(t,{href:"https://linux.cn/"},{default:d(()=>[...e[11]||(e[11]=[o("Linux中国",-1)])]),_:1}),e[14]||(e[14]=o(" 荣誉推出",-1))])])}const T=l(i,[["render",O]]);export{h as __pageData,T as default};
